INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'','بازرسی و نگهداری نوار آبیاری در مزرعه دوزدوزان','','inherit','open','closed','1030005002399-tape20-5',NOW(),UTC_TIMESTAMP(),@post_id,'https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/1030005002399-tape20-5.webp',0,'attachment','image/webp',0 WHERE @created_post=1 AND @media_5 IS NULL;
